def check(cx, cy, r=14):
    return [O(cx, cy, r, r, GN)] + polyline([(cx - 8, cy), (cx - 2, cy + 6), (cx + 8, cy - 6)], 3, CR)


def cross(cx, cy, r, w, c):
    return [line(cx - r, cy - r, cx + r, cy + r, w, c), line(cx + r, cy - r, cx - r, cy + r, w, c)]


def clock(cx, cy, r, h1, h2):
    """Clock face; h1/h2 are hand angles in degrees, 0 = twelve o'clock."""
    tip = lambda a, l: (round(cx + l * math.sin(math.radians(a))), round(cy - l * math.cos(math.radians(a))))
    return [O(cx, cy, r, r, CR, 16), line(cx, cy, *tip(h1, r * 0.55), 5, IN), line(cx, cy, *tip(h2, r * 0.8), 3, IN), O(cx, cy, 4, 4, PK)]


