    assert len(ADJECTIVES) + len(ADVERBS) == 100, (len(ADJECTIVES), len(ADVERBS))
    for pos, words in (("adjective", ADJECTIVES), ("adverb", ADVERBS)):
        taken = [w for w in words if (base.ASSETS / f"word_{w}_{pos}_plate.imageset").exists()]
        assert not taken, f"would overwrite existing imagesets: {taken}"
    if len(sys.argv) > 2 and sys.argv[1] == "json":
        import json
        base.WORDS = {**ADJECTIVES, **ADVERBS}
        print(json.dumps(base.json_for(sys.argv[2]), separators=(",", ":")))
    else:
        for pos, words in (("adjective", ADJECTIVES), ("adverb", ADVERBS)):
            base.POS, base.WORDS = pos, words
            base.main()
